            server = HttpServer.create(new InetSocketAddress(HEALTH_CHECK_PORT), 0);

            // Basic health check endpoint
            server.createContext("/health", new HealthHandler());

            // Ready check endpoint for Kubernetes readiness probes
            server.createContext("/ready", new ReadyHandler());

            // Live check endpoint for Kubernetes liveness probes
            server.createContext("/live", new LiveHandler());

            server.setExecutor(null);
            server.start();

            System.out.println("Health check server started on port: " + HEALTH_CHECK_PORT);
            System.out.println("Health endpoints:");
            System.out.println("  - /health - Basic health check");
            System.out.println("  - /ready - Readiness probe");
            System.out.println("  - /live - Liveness probe");

        } catch (IOException e) {
            System.err.println("Failed to start health check server: " + e.getMessage());
        }
    }

    public void stopHealthCheckServer() {
        if (server != null) {
            server.stop(0);
            System.out.println("Health check server stopped");
        }
    }

    // Basic health check handler
    static class HealthHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            Map<String, Object> health = new HashMap<>();
            health.put("status", "UP");
            health.put("timestamp", System.currentTimeMillis());
            health.put("application", "mini-java-app");

            String response = createJsonResponse(health);
            sendResponse(exchange, 200, response);
        }
    }

    // Readiness check handler - checks if application is ready to serve requests
    static class ReadyHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            Map<String, Object> ready = new HashMap<>();
            boolean isReady = true;

            // Check database connectivity
            try {
                checkDatabaseConnection();
                ready.put("database", "UP");
            } catch (Exception e) {
                ready.put("database", "DOWN");
                ready.put("database_error", e.getMessage());
                isReady = false;
            }

            ready.put("status", isReady ? "READY" : "NOT_READY");
            ready.put("timestamp", System.currentTimeMillis());

            String response = createJsonResponse(ready);
            sendResponse(exchange, isReady ? 200 : 503, response);
        }
    }

    // Liveness check handler - checks if application is alive
    static class LiveHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            Map<String, Object> live = new HashMap<>();
            live.put("status", "ALIVE");
            live.put("timestamp", System.currentTimeMillis());
            live.put("uptime", System.currentTimeMillis() - startTime);

            String response = createJsonResponse(live);
            sendResponse(exchange, 200, response);
        }
    }

    private static long startTime = System.currentTimeMillis();

    private static void checkDatabaseConnection() throws SQLException, ClassNotFoundException {
        String dbHost = System.getenv().getOrDefault("DB_HOST", "localhost");
        String dbPort = System.getenv().getOrDefault("DB_PORT", "3306");
        String dbName = System.getenv().getOrDefault("DB_NAME", "mini_app_db");
        String dbUrl = "jdbc:mysql://" + dbHost + ":" + dbPort + "/" + dbName;
        String dbUsername = System.getenv().getOrDefault("DB_USERNAME", "root");
        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "password123");

        Class.forName("com.mysql.cj.jdbc.Driver");
        try (Connection connection = DriverManager.getConnection(dbUrl, dbUsername, dbPassword)) {
            // Connection successful
        }
    }

    private static String createJsonResponse(Map<String, Object> data) {
        StringBuilder json = new StringBuilder();
        json.append("{");

        boolean first = true;
        for (Map.Entry<String, Object> entry : data.entrySet()) {
            if (!first) {
                json.append(",");
            }
            json.append("\"").append(entry.getKey()).append("\":");

            Object value = entry.getValue();
            if (value instanceof String) {
                json.append("\"").append(value).append("\"");
            } else {
                json.append(value);
            }

            first = false;
        }

        json.append("}");
        return json.toString();
    }

    private static void sendResponse(HttpExchange exchange, int statusCode, String response) throws IOException {
        exchange.getResponseHeaders().set("Content-Type", "application/json");
        exchange.sendResponseHeaders(statusCode, response.getBytes().length);

        try (OutputStream os = exchange.getResponseBody()) {
            os.write(response.getBytes());
        }
    }
